<script setup lang="ts">
import {ref} from 'vue'
import {useRouter} from 'vue-router'
import {Sprout,ArrowUpRight,Leaf,Heart,ScanLine} from 'lucide-vue-next'
import {login,post} from '../api'
import {ElMessage} from 'element-plus'
const router=useRouter(),register=ref(false),username=ref(''),password=ref(''),confirm=ref(''),busy=ref(false)
async function submit(){if(register.value&&password.value!==confirm.value){ElMessage.warning('两次密码不一致');return}busy.value=true;try{if(register.value){await post('/auth/register',{username:username.value,password:password.value});ElMessage.success('注册成功，正在登录')}await login(username.value,password.value);await router.push('/')}finally{busy.value=false}}
</script>
<template><div class="login-page"><div class="login-story"><div class="brand"><span class="brand-mark"><Sprout/></span><b>膳衡</b><span class="brand-en">SHANHENG</span></div><div class="story-body"><span class="eyebrow light">SMART CAMPUS · MINDFUL EATING</span><h1>每一餐，<br>都刚刚好<span>。</span></h1><p>让科技看见每一份珍惜，<br>让健康与可持续，成为校园日常。</p><div class="story-art"><img src="/assets/hero.svg" alt="均衡的校园午餐插画"></div><div class="story-features"><span><ScanLine/>智慧监测</span><span><Heart/>营养搭配</span><span><Leaf/>绿色校园</span></div></div><div class="small story-footer">膳衡 · 高校智慧食堂平台 <ArrowUpRight :size="16"/></div></div><div class="login-form-wrap"><div class="login-form"><span class="eyebrow">WELCOME TO SHANHENG</span><h2>{{register?'开启健康校园生活':'欢迎回来'}}</h2><p class="muted">{{register?'创建学生账号，开启你的专属饮食计划':'登录账号，发现适合你的每一餐。'}}</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="账号"><el-input v-model="username" placeholder="3–40位字母、数字、下划线" autocomplete="username" size="large"/></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" show-password placeholder="至少8位密码" :autocomplete="register?'new-password':'current-password'" size="large"/></el-form-item><el-form-item v-if="register" label="确认密码"><el-input v-model="confirm" type="password" show-password size="large"/></el-form-item><el-button class="full" type="primary" size="large" native-type="submit" :loading="busy">{{register?'注册并登录':'登录平台'}} <ArrowUpRight :size="16"/></el-button></el-form><div class="login-switch"><span class="muted">{{register?'已有账号？':'还没有账号？'}}</span><el-button link type="primary" @click="register=!register">{{register?'立即登录':'创建账号'}}</el-button></div><div class="demo-accounts"><b>本地演示入口</b><p class="muted small">初始化演示数据后，可选择角色体验。密码：Demo@12345</p><div class="row"><el-button v-for="(label,key) in {student:'学生端',manager:'食堂端',admin:'管理端'}" :key="key" @click="username=key;password='Demo@12345';register=false">{{label}}</el-button></div></div><p class="muted small">身体信息自愿填写 · 回收监测匿名统计</p></div></div></div></template>
